  const nodeCrypto = await import('node:crypto');
  globalThis.crypto = globalThis.crypto || {};
  globalThis.crypto.subtle = nodeCrypto.webcrypto;
  globalThis.btoa = (str: string) => Buffer.from(str, 'binary').toString('base64');
