import { handle, ConnectorConfig, ShopifyOrderWebhookPayload, HandleResult } from './connector';
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  TARGET_ENDPOINTS,
} from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const rawBody = JSON.stringify(SOURCE_EXAMPLE);
    const secret = 'test-shared-secret';
    const encoder = new TextEncoder();
    const key = await crypto.subtle.importKey(
      'raw',
      encoder.encode(secret),
      { name: 'HMAC', hash: 'SHA-256' },
      false,
      ['sign']
    );
    const hmac = await crypto.subtle.sign('HMAC', key, encoder.encode(rawBody));
    const bytes = new Uint8Array(hmac);
    let binary = '';
    for (const byte of bytes) binary += String.fromCharCode(byte);
    const signature = btoa(binary);

    const config: ConnectorConfig = {
      shopifySharedSecret: secret,
      slackBotToken: 'xoxb-test-token',
      slackChannel: 'C1234567890',
      fetch,
      rawBody,
      shopifySignature: signature,
    };

    const result = await handle(SOURCE_EXAMPLE as unknown as ShopifyOrderWebhookPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.slackChannel).toBe('C1234567890');
    expect(result.slackTs).toBe('1234567890.123456');
  });
});

describe('handle', () => {
  it('sends correct Slack message with field mapping', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://slack.com/api/chat.postMessage' && req.method === 'POST') {
        return jsonResponse({
          ok: true,
          channel: 'C1234567890',
          ts: '1234567890.123456',
          message: { text: 'dummy', username: 'bot', bot_id: 'B1' },
        });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const config: ConnectorConfig = {
      shopifySharedSecret: 'secret',
      slackBotToken: 'xoxb-token',
      slackChannel: 'C1234567890',
      fetch,
      rawBody: JSON.stringify(SOURCE_EXAMPLE),
      shopifySignature: 'dummy', // will fail verification but we skip by not providing? Actually we provide rawBody and signature, so verification runs. Let's provide a valid signature.
    };

    // Generate valid signature for this test
    const rawBody = JSON.stringify(SOURCE_EXAMPLE);
    const encoder = new TextEncoder();
    const key = await crypto.subtle.importKey(
      'raw',
      encoder.encode(config.shopifySharedSecret),
      { name: 'HMAC', hash: 'SHA-256' },
      false,
      ['sign']
    );
    const hmac = await crypto.subtle.sign('HMAC', key, encoder.encode(rawBody));
    const bytes = new Uint8Array(hmac);
    let binary = '';
    for (const byte of bytes) binary += String.fromCharCode(byte);
    config.shopifySignature = btoa(binary);
    config.rawBody = rawBody;

    const result = await handle(SOURCE_EXAMPLE as unknown as ShopifyOrderWebhookPayload, config);

    expect(calls.length).toBe(1);
    const call = calls[0];
    expect(call.method).toBe('POST');
    expect(call.url).toBe('https://slack.com/api/chat.postMessage');
    expect(call.headers.get('authorization')).toBe('Bearer xoxb-token');
    expect(call.json).toEqual({
      channel: 'C1234567890',
      text: 'New order #1001 from customer@example.com for $123.45 USD: 2 x T-Shirt',
    });
    expect(result.slackChannel).toBe('C1234567890');
    expect(result.slackTs).toBe('1234567890.123456');
  });

  it('throws on missing required field', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config: ConnectorConfig = {
      shopifySharedSecret: 'secret',
      slackBotToken: 'xoxb-token',
      slackChannel: 'C1234567890',
      fetch,
    };
    const badPayload = { ...SOURCE_EXAMPLE, id: undefined } as unknown as ShopifyOrderWebhookPayload;
    await expect(handle(badPayload, config)).rejects.toThrow('Missing required field: id');
  });

  it('throws on non-2xx Slack response', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'invalid_auth' }, 401));
    const config: ConnectorConfig = {
      shopifySharedSecret: 'secret',
      slackBotToken: 'xoxb-token',
      slackChannel: 'C1234567890',
      fetch,
    };
    await expect(handle(SOURCE_EXAMPLE as unknown as ShopifyOrderWebhookPayload, config)).rejects.toThrow(
      'Slack API error: 401 Unauthorized for POST https://slack.com/api/chat.postMessage'
    );
  });

  it('throws on HMAC verification failure', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config: ConnectorConfig = {
      shopifySharedSecret: 'secret',
      slackBotToken: 'xoxb-token',
      slackChannel: 'C1234567890',
      fetch,
      rawBody: JSON.stringify(SOURCE_EXAMPLE),
      shopifySignature: 'invalid-signature',
    };
    await expect(handle(SOURCE_EXAMPLE as unknown as ShopifyOrderWebhookPayload, config)).rejects.toThrow(
      'HMAC-SHA256 signature verification failed'
    );
  });

  it('uses injected fetch from config', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://slack.com/api/chat.postMessage') {
        return jsonResponse({
          ok: true,
          channel: 'C1234567890',
          ts: '1234567890.123456',
          message: { text: 'dummy', username: 'bot', bot_id: 'B1' },
        });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const config: ConnectorConfig = {
      shopifySharedSecret: 'secret',
      slackBotToken: 'xoxb-token',
      slackChannel: 'C1234567890',
      fetch,
      rawBody: JSON.stringify(SOURCE_EXAMPLE),
      shopifySignature: 'dummy',
    };
    // Generate valid signature
    const rawBody = JSON.stringify(SOURCE_EXAMPLE);
    const encoder = new TextEncoder();
    const key = await crypto.subtle.importKey(
      'raw',
      encoder.encode(config.shopifySharedSecret),
      { name: 'HMAC', hash: 'SHA-256' },
      false,
      ['sign']
    );
    const hmac = await crypto.subtle.sign('HMAC', key, encoder.encode(rawBody));
    const bytes = new Uint8Array(hmac);
    let binary = '';
    for (const byte of bytes) binary += String.fromCharCode(byte);
    config.shopifySignature = btoa(binary);

    await handle(SOURCE_EXAMPLE as unknown as ShopifyOrderWebhookPayload, config);
    expect(calls.length).toBe(1);
    expect(calls[0].url).toBe('https://slack.com/api/chat.postMessage');
  });
});

# Shopify to Slack Order Notification Connector

This connector receives Shopify `orders/paid` webhook payloads, verifies the HMAC-SHA256 signature using the shared secret, and forwards a formatted order summary to a configured Slack channel via the `chat.postMessage` API.

## What it does

1. **Validates** the incoming Shopify webhook payload for required fields (`id`, `name`, `email`, `total_price`, `currency`, `line_items`).
2. **Verifies** the `X-Shopify-Hmac-Sha256` header against the raw request body using the shared secret (if `rawBody` and `shopifySignature` are provided in config).
3. **Constructs** a human-readable message:  
   `New order {name} from {email} for ${total_price} {currency}: {qty} x {title}, ...`
4. **Posts** the message to Slack using a bot token with `chat:write` scope.
5. **Returns** the Slack channel ID and message timestamp (`ts`) for tracking.

## Configuration / Environment Variables

| Config Property | Environment Variable | Description |
|-----------------|----------------------|-------------|
| `shopifySharedSecret` | `SHOPIFY_SHARED_SECRET` | The shared secret from Shopify webhook configuration, used to compute HMAC-SHA256. |
| `slackBotToken` | `SLACK_BOT_TOKEN` | Slack bot token with `chat:write` scope (starts with `xoxb-`). |
| `slackChannel` | `SLACK_CHANNEL` | Slack channel ID (e.g., `C1234567890`) or name (e.g., `#orders`). |
| `fetch` | — | Optional injected `fetch` implementation (for testing or non-standard runtimes). |
| `rawBody` | — | Optional raw request body string (for HMAC verification). |
| `shopifySignature` | — | Optional `X-Shopify-Hmac-Sha256` header value (for HMAC verification). |

**Required:** `shopifySharedSecret`, `slackBotToken`, `slackChannel`.  
**Optional but recommended for security:** `rawBody`, `shopifySignature` (provided by the webhook framework).

## Usage Example

```typescript
import { handle, ConnectorConfig, ShopifyOrderWebhookPayload } from './connector';

const config: ConnectorConfig = {
  shopifySharedSecret: process.env.SHOPIFY_SHARED_SECRET!,
  slackBotToken: process.env.SLACK_BOT_TOKEN!,
  slackChannel: process.env.SLACK_CHANNEL!,
  // In a real webhook handler, also pass:
  // rawBody: request.bodyText,           // raw request body as string
  // shopifySignature: request.headers.get('X-Shopify-Hmac-Sha256') || '',
};

const payload: ShopifyOrderWebhookPayload = await request.json(); // parsed JSON

try {
  const result = await handle(payload, config);
  console.log('Posted to Slack:', result.slackChannel, result.slackTs);
  return new Response('OK', { status: 200 });
} catch (err) {
  console.error('Connector error:', err);
  return new Response('Bad Request', { status: 400 });
}
```

## Assumptions

- The webhook payload includes the standard Shopify order fields: `id`, `name`, `email`, `total_price`, `currency`, and `line_items` (each with `title`, `quantity`, `price`).
- The integration has access to the Shopify shared secret to compute the HMAC-SHA256 digest for verification.
- The Slack channel ID or name is known and configured in the Slack action step.
- The message text is constructed by concatenating the mapped fields into a readable summary.
- The runtime provides the Web Crypto API (`crypto.subtle`) for HMAC-SHA256 (available in modern browsers, Cloudflare Workers, Deno, Bun; polyfill needed in Node.js).
- The connector responds with 200 OK quickly to avoid Shopify webhook retries.
- Slack rate limits (~1 message/second/channel) are respected by the caller.

